279:               "enum": ["standard", "platform", "system", "ffi", "hardware"],
280:               "description": "按可移植性分类。standard=语言标准库/运行时,到处可用(C++ STL、Python stdlib、JDK标准包、Node内置); platform=某OS专有,换平台即没有(Win32 与 POSIX-only 如 mmap/fork/epoll/<unistd.h> 都属此,再用 platform 字段标 windows/posix/macos); system=内核/系统调用层(裸 syscall、ioctl、/proc、/sys、注册表、WMI、设备); ffi=互操作桥(ctypes/cffi/JNI/N-API); hardware=GPU/SIMD/加速器"},
281:             "platform": {"type": "string",
282:               "enum": ["windows", "posix", "linux", "macos", "portable", "unknown"],
283:               "description": "该组 API 所属平台；portable=跨平台(标准库)"},
284:             "apis": {"type": "array",
285:               "description": "逐个具体 API（代表性，非穷举）",
286:               "items": {
