291:                   "purpose": {"type": "string", "description": "中文：该 API 的作用"},
292:                   "count": {"type": "integer", "description": "调用次数/出现次数（代表性近似，grep -c 或 codegraph callers）"},
293:                   "evidence": {"type": "array", "items": {"type": "string"},
294:                     "description": "调用位置 file:line（代表性 1-3 处）"},
295:                   "conditional": {"type": "boolean", "description": "是否被 #ifdef / 平台条件守卫"}}}},
296:             "evidence": {"type": "array", "items": {"type": "string"},
297:               "description": "group-level files / includes (optional; prefer per-api evidence)"}}}},
